import io
import csv

data = io.StringIO("kota,total\n" + "\n".join(f"{k},{t}" for k, t in
    [("Medan", 100), ("Medan", 300), ("Bandung", 50), ("Medan", 200), ("Bandung", 150), ("Bandung", 100)]))

jumlah, hitung = {}, {}
potongan = []
def olah(baris):
    for b in baris:
        k = b["kota"]
        jumlah[k] = jumlah.get(k, 0) + int(b["total"])
        hitung[k] = hitung.get(k, 0) + 1

for b in csv.DictReader(data):
    potongan.append(b)
    if len(potongan) == 4:
        olah(potongan)
        potongan = []
olah(potongan)
for k in jumlah:
    print(k, "rata-rata", jumlah[k] / hitung[k])

import pandas as pd

def rapikan_kota(df):
    return df.assign(kota=df["kota"].str.strip().str.title())

def buang_kecil(df, minimal):
    return df[df["total"] >= minimal]

mentah = pd.DataFrame({"kota": [" medan", "BANDUNG", "medan ", "ambon"], "total": [50000, 120000, 8000, 75000]})
hasil = mentah.pipe(rapikan_kota).pipe(buang_kecil, minimal=10_000)
print(hasil)

import polars as pl

df = pl.DataFrame({
    "kota": ["Medan", "Bandung", "Medan", "Ambon", "Bandung"],
    "total": [125000, 89000, 240000, 56000, 310000],
})
print(
    df.group_by("kota")
      .agg(pl.col("total").sum().alias("omzet"), pl.len().alias("order"))
      .sort("omzet", descending=True)
)
